head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataMap > M > getArray]<br/>DataMap 모듈의 전체 데이터를 배열로 반환합니다.",
    "validation" : [
        "DataMap 모듈의 전체 데이터를 Key 가 정의된 순서대로 배열로 반환합니다.",
        "배열의 각 원소는 Key 에 할당된 값(Value)이 설정됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }    

    if (typeof input1 !== 'undefined') {
        input1.remove();
    }    

    // target 생성
    $c.gcm.createBasicDataMap();

    // input 생성
    $c.gcm.createEmptyInput('ref="data:target1.key1" style="width:200px;"', '', 'input1');

    scwin.btn_getArray_onclick();
}



scwin.btn_getArray_onclick = function (e) {
    let rtn = target1.getArray();

    wf_body_bottom.getObj("scwin").setReturnValue("getArray : " + rtn);  
};
